def card_svg(text: str) -> str:
    """Escape, wrap, and center `text` in the card; return SVG string."""
    text = " ".join(text.split()) # collapse newlines/extra spaces
    # ~0.55 em average glyph width is the usual estimate for wrapping math
    chars_per_line = int((CARD_W - 2 * MARGIN) / (FONT_SIZE * 0.55))
    lines = textwrap.wrap(
        text,
        width=chars_per_line,
        max_lines=(CARD_H - 2 * MARGIN) // int(FONT_SIZE * LINE_SPACING),
        placeholder="…",)
    
    total_h = len(lines) * LINE_HEIGHT
    y0 = (CARD_H - total_h) / 2 + FONT_SIZE     # first baseline, vertically centered
    tspan_elements = "\n".join(
        f'      <tspan x="{CARD_W / 2}" y="{y0 + i * LINE_HEIGHT:.0f}">{xml_escape(line)}</tspan>'
        for i, line in enumerate(lines)
    )

    h_safe=CARD_H - 2 * MARGIN
    text_element = f' <text text-anchor="middle" font-family="{FONT_FAMILY}" font-size="{FONT_SIZE}" fill="{INK}">\n{tspan_elements}</text>'
    
    return  f"""<?xml version="1.0" encoding="UTF-8"?>
    <svg width="{CARD_W}" height="{CARD_H}" viewBox="0 0 {CARD_W} {CARD_H}" xmlns="http://www.w3.org/2000/svg">
     <rect id="background" width="{CARD_W}" height="{CARD_H}" fill="{PAPER}"/>
     <rect id="safe-zone" width="{CARD_W}" height="{h_safe}" y="{MARGIN}" fill="none"/>
    {logo}
    {text_element}
    </svg>"""


def main() -> int:
    parser = argparse.ArgumentParser(description="Create a musing style post.")
    parser.add_argument("title", nargs="?", default=title, help="Post title (default: Lorem ipsum)")
    parser.add_argument("text", nargs="?", default=text, help="Post content (default: Lorem ipsum text)")
    args = parser.parse_args()
    
    slug = f"{str(date.today())}_{slugify(args.title)}"
    today = str(date.today())
    title_bar = "="*len(args.title)

    rst = '\n'.join([title_bar, args.title, title_bar, 
               f":date: {today}", f":modified: {today}",
               ":author: pairko", 
               ":category: musing",
               ":summary: ",
               f":description: {args.text}",
               f":tags: ", f":slug: {slug}",f":lang: en",
               f":og_image:  https://raspberrypi.tailcd13e6.ts.net/musings/{slug}/social.jpg",
               "", args.text])

    # create folders
    """
    /content
        /musings
            /{slug}
                en.rst
                social.jpg
                [social.png] temporary
                /working
                    {slug}.svg
    """

    musings_dir = "content/musings"
    musings_dir  = Path(musings_dir).resolve()
    if not musings_dir .is_dir():
        raise NotADirectoryError(f"Not a directory: {musings_dir}")

    working_dir = musings_dir / 'working'
    if not working_dir.is_dir():
        working_dir.mkdir()
    
    post_dir = working_dir / slug
    if post_dir.is_dir():
        shutil.rmtree(post_dir)
    post_dir.mkdir()
    
    rst_file = post_dir / "en.rst"
    rst_file.write_text(rst, encoding="utf-8")
    
    post_working = post_dir / 'working'
    post_working.mkdir()

    svg_template = post_working / f"{slug}.svg"
    svg_template.write_text(card_svg(args.text), encoding="utf-8")
    png_dest = post_working / "social.png"
    jpg_dest = post_dir / "social.jpg"
    cairosvg.svg2png(url=str(svg_template), write_to=str(png_dest))
    Image.open(png_dest).convert("RGB").save(jpg_dest, "JPEG", quality=90)
    os.remove(png_dest)
    return 0            

if __name__ == "__main__":
    sys.exit(main())
    